-- STAGING ONLY. 8 branch-identified restaurants with cuisine, dish and select independently described ambience.
-- Subjective traits (quiet/cozy/date/group) are explicitly source-attributed, not inferred from permit category.
-- See venue references in evidence_ref. Other venues remain unreviewed candidates.
 ON CONFLICT(restaurant_id,tag_code) DO UPDATE SET
 verification_state='verified',
 evidence_ref=EXCLUDED.evidence_ref,
 verified_at=EXCLUDED.verified_at
 WHERE restaurant_tag_assignments.verification_state='proposed';
